const adj = { out: Map<id, edge[]>, in: Map<id, edge[]> };
function walk(startId, dir){ // dir 'deps' follows out, 'impact' follows in
  const dist = new Map([[startId, 0]]);
  const q = [startId];
  while (q.length) {
    const u = q.shift();
    const list = dir === 'deps' ? adj.out.get(u) : adj.in.get(u);
    for (const e of list) {
      const v = dir === 'deps' ? e.to : e.from;
      if (!dist.has(v)) { dist.set(v, dist.get(u) + 1); q.push(v); }
    }
  }
  return dist;
}
