  color: var(--ink-2); font-size: 11.5px;
  transition: color .12s, border-color .12s;
}
.act-btn:hover { color: var(--ink); border-color: var(--muted); }
.act-btn.blue { color: var(--dep); border-color: rgba(57,135,229,.4); }
