  --t-access:   #9085e9;
  --t-external: #8a93a3;
  /* 状态（保留色，配文字标签使用） */
  --critical: #d03b3b;
  --warning:  #fab219;
  --trail:    #e8edf5;
  --font: "Segoe UI", "Microsoft YaHei", "PingFang SC", system-ui, sans-serif;
