    check('path-impact-mirror', !!state.pathResult.impact, state.pathResult.impact ? state.pathResult.impact.nodes.join('>') : 'null');
    // 5. 关系选择（边 = 内容）
    exitPathMode(); selectEdge(EDGES.find(e => e.from === 'order-svc' && e.to === 'pg-orders').id);
    check('edge-select-renders', state.sel.kind === 'edge' && document.getElementById('panel').textContent.includes('关系详情'));
    // 6. 覆盖统计
    resetAll();
    check('reset-overview', state.sel === null && state.trail.length === 0);
    // 还原首屏
    follow('order-svc', null);
  } catch (err) {
    out.push({ name: 'exception', pass: false, detail: err.message });
  }
  const pass = out.every(o => o.pass);
  const report = { pass, steps: out };
  let div = document.getElementById('selftest-report');
  if (!div) {
    div = document.createElement('div');
    div.id = 'selftest-report';
    div.style.cssText = 'position:fixed;left:8px;top:8px;z-index:9999;background:#0e1218;color:#e8edf5;border:1px solid #3987e5;padding:10px 14px;font:11px/1.6 monospace;max-width:520px;white-space:pre-wrap';
