/* ============================================================
 * 脉络 Trace · 样式层
 * 色板：dataviz 已验证暗色系（系列色 slots 3-7 + 方向强调 slots 1-2，
 * 状态色保留给 P0/P1，全部带文字标签不作唯一编码）
 * ============================================================ */

:root {
  color-scheme: dark;
  /* 表面与墨色 */
  --bg:        #0e1218;   /* 页面平面 */
  --surface:   #141922;   /* 图表表面 */
  --surface-2: #1a212c;   /* 抬升面板 */
  --surface-3: #212a37;   /* 悬停 / 选中底 */
  --line:      #273040;   /* 发丝分隔 */
  --ink:       #f0f3f8;   /* 主墨 */
  --ink-2:     #aeb7c4;   /* 次墨 */
  --muted:     #7d8798;   /* 弱墨 */
  /* 方向强调（核心语义） */
  --dep:      #3987e5;    /* 蓝 = 依赖方向 */
  --impact:   #d95926;    /* 橙 = 影响方向 */
  /* 节点类型（固定顺序子集：slots 3,4,5,7 + 中性） */
  --t-service:  #199e70;
  --t-topic:    #c98500;
  --t-data:     #d55181;
  --t-access:   #9085e9;
  --t-external: #8a93a3;
  /* 状态（保留色，配文字标签使用） */
  --critical: #d03b3b;
  --warning:  #fab219;
  --trail:    #e8edf5;
  --font: "Segoe UI", "Microsoft YaHei", "PingFang SC", system-ui, sans-serif;
}

